package de.teamlapen.vampirism.common.world.blockentity;

import com.mojang.serialization.Codec;
import de.teamlapen.faction.api.factions.skills.ISkillHandler;
import de.teamlapen.faction.common.components.FactionRestriction;
import de.teamlapen.faction.common.world.blockentity.NetworkedContainerBlockEntity;
import de.teamlapen.vampirism.VampirismMod;
import de.teamlapen.vampirism.common.core.ModBlockEntities;
import de.teamlapen.vampirism.common.core.ModFactions;
import de.teamlapen.vampirism.common.core.ModRecipes;
import de.teamlapen.vampirism.common.util.Helper;
import de.teamlapen.vampirism.common.world.blocks.AlchemicalCauldronBlock;
import de.teamlapen.vampirism.common.world.entity.player.hunter.HunterPlayer;
import de.teamlapen.vampirism.common.world.entity.player.hunter.skills.HunterSkills;
import de.teamlapen.vampirism.common.world.inventory.AlchemicalCauldronMenu;
import de.teamlapen.vampirism.common.world.items.recipes.AlchemicalCauldronRecipe;
import de.teamlapen.vampirism.common.world.items.recipes.AlchemicalCauldronRecipeInput;
import it.unimi.dsi.fastutil.objects.Object2IntOpenHashMap;
import net.minecraft.core.*;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.Mth;
import net.minecraft.world.ContainerHelper;
import net.minecraft.world.WorldlyContainer;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.player.StackedItemContents;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.ContainerData;
import net.minecraft.world.inventory.RecipeCraftingHolder;
import net.minecraft.world.inventory.StackedContentsCompatible;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.ItemStackTemplate;
import net.minecraft.world.item.crafting.Recipe;
import net.minecraft.world.item.crafting.RecipeHolder;
import net.minecraft.world.item.crafting.RecipeManager;
import net.minecraft.world.item.crafting.RecipeType;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.AbstractFurnaceBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.capabilities.Capabilities;
import net.neoforged.neoforge.transfer.ResourceHandler;
import net.neoforged.neoforge.transfer.access.ItemAccess;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.item.VanillaContainerWrapper;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import org.jetbrains.annotations.Nullable;

import java.util.Map;
import java.util.Optional;
import java.util.UUID;

/**
 * slots:  0: liquid, 1: ingredient, 2: result, 3: fuel
 */
public class AlchemicalCauldronBlockEntity extends NetworkedContainerBlockEntity implements WorldlyContainer, RecipeCraftingHolder, StackedContentsCompatible {
    private static final Codec<Map<ResourceKey<Recipe<?>>, Integer>> RECIPES_USED_CODEC = Codec.unboundedMap(Recipe.KEY_CODEC, Codec.INT);

    private static final int[] SLOTS_DOWN = new int[] {0, 1, 2};
    private static final int[] SLOTS_UP = new int[] {0};
    private static final int[] SLOTS_WEST = new int[] {1};
    private static final int[] SLOTS_FUEL = new int[] {3};

    @Nullable
    private UUID ownerID;
    @Nullable
    private String ownerName;
    private @Nullable RecipeHolder<AlchemicalCauldronRecipe> recipeChecked;
    private final RecipeType<? extends AlchemicalCauldronRecipe> recipeType;
    protected NonNullList<ItemStack> items;
    protected int litTime;
    protected int litDuration;
    protected int cookingProgress;
    protected int cookingTotalTime;

    protected final ContainerData dataAccess = new ContainerData() {
        @Override
        public int get(int slot) {
            return switch (slot) {
                case 0 -> {
                    if (litDuration > Short.MAX_VALUE) {
                        // Neo: preserve litTime / litDuration ratio on the client as data slots are synced as shorts.
                        yield Mth.floor(((double) litTime / litDuration) * Short.MAX_VALUE);
                    }

                    yield AlchemicalCauldronBlockEntity.this.litTime;
                }
                case 1 -> Math.min(AlchemicalCauldronBlockEntity.this.litDuration, Short.MAX_VALUE);
                case 2 -> AlchemicalCauldronBlockEntity.this.cookingProgress;
                case 3 -> AlchemicalCauldronBlockEntity.this.cookingTotalTime;
                default -> 0;
            };
        }

        @Override
        public void set(int p_58433_, int p_58434_) {
            switch (p_58433_) {
                case 0:
                    AlchemicalCauldronBlockEntity.this.litTime = p_58434_;
                    break;
                case 1:
                    AlchemicalCauldronBlockEntity.this.litDuration = p_58434_;
                    break;
                case 2:
                    AlchemicalCauldronBlockEntity.this.cookingProgress = p_58434_;
                    break;
                case 3:
                    AlchemicalCauldronBlockEntity.this.cookingTotalTime = p_58434_;
            }
        }

        @Override
        public int getCount() {
            return 4;
        }
    };

    private final Object2IntOpenHashMap<ResourceKey<Recipe<?>>> recipesUsed = new Object2IntOpenHashMap<>();
    private final RecipeManager.CachedCheck<AlchemicalCauldronRecipeInput, AlchemicalCauldronRecipe> quickCheck;


    public AlchemicalCauldronBlockEntity(BlockPos pos, BlockState state) {
        super(ModBlockEntities.ALCHEMICAL_CAULDRON.get(), pos, state);
        this.recipeType = ModRecipes.ALCHEMICAL_CAULDRON_TYPE.get();
        this.items = NonNullList.withSize(4, ItemStack.EMPTY);
        this.quickCheck = RecipeManager.createCheck(ModRecipes.ALCHEMICAL_CAULDRON_TYPE.get());
    }

    public ItemStack getFluid() {
        return this.items.getFirst();
    }

    public ItemStack getIngredient() {
        return this.items.get(1);
    }


    @Nullable
    @Override
    public AbstractContainerMenu createMenu(int containerId, Inventory inventory, Player player) {
        if (canOpen(player)) {
            if (!Helper.isHunter(player)) {
                player.sendOverlayMessage(FactionRestriction.getFactionRestrictionMessage(ModFactions.HUNTER.get()));
            } else if (HunterPlayer.get(player).getSkillHandler().isSkillEnabled(HunterSkills.BASIC_ALCHEMY)) {
                if (ownerID == null) {
                    setOwnerID(player);
                }
                if (ownerID.equals(player.getUUID())) {
                    return this.createMenu(containerId, inventory);
                } else {
                    player.sendOverlayMessage(Component.translatable("message.vampirism.alchemical_cauldron.other_owner", getOwnerName()));
                }
            } else {
                player.sendOverlayMessage(FactionRestriction.MESSAGE_MISSING_SKILLS);
            }
        }
        return null;
    }

    @Override
    protected void setItems(NonNullList<ItemStack> pItems) {
        this.items = pItems;
    }

    @Override
    public NonNullList<ItemStack> getItems() {
        return this.items;
    }

    @Override
    public Component getCustomName() {
        return Component.translatable("container.vampirism.alchemical_cauldron");
    }

    @Override
    public Component getDisplayName() {
        return Component.translatable("container.vampirism.alchemical_cauldron.owner", getOwnerName());
    }

    public Component getOwnerName() {
        return Component.literal(ownerName == null ? "Unknown" : ownerName);
    }

    @Override
    public int [] getSlotsForFace(Direction side) {
        if (side == Direction.DOWN) {
            return SLOTS_DOWN;
        } else {
            return side == Direction.UP ? SLOTS_UP : side == Direction.WEST ? SLOTS_WEST : SLOTS_FUEL;
        }
    }

    @Override
    public boolean canPlaceItemThroughFace(int pIndex, ItemStack pItemStack, @Nullable Direction pDirection) {
        return false;
    }

    @Override
    public boolean canTakeItemThroughFace(int pIndex, ItemStack pStack, Direction pDirection) {
        return false;
    }


    @Override
    protected void loadAdditional(ValueInput input) {
        super.loadAdditional(input);
        this.ownerID = input.read("owner", UUIDUtil.CODEC).orElse(null);
        this.ownerName = input.getString("owner_name").orElse(null);
        this.items = NonNullList.withSize(this.getContainerSize(), ItemStack.EMPTY);
        ContainerHelper.loadAllItems(input, this.items);
        this.litTime = input.getIntOr("BurnTime", this.litTime);
        this.litDuration = input.getIntOr("lit_duration", 0);
        this.cookingProgress = input.getIntOr("CookTime", this.cookingProgress);
        this.cookingTotalTime = input.getIntOr("CookTimeTotal", this.cookingTotalTime);
        this.recipesUsed.clear();
        this.recipesUsed.putAll(input.read("RecipesUsed", RECIPES_USED_CODEC).orElse(Map.of()));
    }

    protected int getBurnDuration(ItemStack pFuel) {
        if (pFuel.isEmpty()) {
            return 0;
        } else {
            return pFuel.getBurnTime(this.recipeType, this.level.fuelValues());
        }
    }

    private boolean isLit() {
        return this.litTime > 0;
    }

    @Override
    public void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);
        output.putInt("BurnTime", this.litTime);
        output.putInt("lit_duration", this.litDuration);
        output.putInt("CookTime", this.cookingProgress);
        output.putInt("CookTimeTotal", this.cookingTotalTime);
        ContainerHelper.saveAllItems(output, this.items);
        output.store("RecipesUsed", RECIPES_USED_CODEC, this.recipesUsed);
        if (ownerID != null) {
            output.store("owner", UUIDUtil.CODEC, ownerID);
        }
        if (ownerName != null) {
            output.putString("owner_name", ownerName);

        }
    }

    @Override
    public void setChanged() {
        if (level != null) {
            super.setChanged();
            BlockState old = level.getBlockState(this.worldPosition);
            BlockState state = old.setValue(AbstractFurnaceBlock.LIT, this.isBurning()).setValue(AlchemicalCauldronBlock.LIQUID, this.items.getFirst().isEmpty() ? AlchemicalCauldronBlock.LiquidState.NONE : this.isBurning() ? AlchemicalCauldronBlock.LiquidState.BOILING : AlchemicalCauldronBlock.LiquidState.FILLED);
            if (old.equals(state)) {
                this.level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 2);
            } else {
                this.level.setBlock(this.worldPosition, state, 3);
            }
        }
    }

    @Override
    public int getContainerSize() {
        return this.items.size();
    }

    @Override
    public void setItem(int pIndex, ItemStack pStack) {
        ItemStack itemstack = this.items.get(pIndex);
        boolean flag = !pStack.isEmpty() && ItemStack.isSameItemSameComponents(itemstack, pStack);
        this.items.set(pIndex, pStack);
        pStack.limitSize(this.getMaxStackSize(pStack));
        if ((pIndex == AlchemicalCauldronMenu.FLUID_SLOT || pIndex == AlchemicalCauldronMenu.INGREDIENT_SLOT) && !flag) {
            if (this.level instanceof ServerLevel serverLevel) {
                this.cookingTotalTime = getTotalCookTime(serverLevel, this);
            }
            this.cookingProgress = 0;
            this.setChanged();
        }
    }

    public void setOwnerID(Player player) {
        ownerID = player.getUUID();
        ownerName = player.getGameProfile().name();
        this.setChanged();
    }

    public Optional<ISkillHandler<?>> getPlayerSkillHandler() {
        if (this.level == null || this.ownerID == null) return Optional.empty();
        return Optional.ofNullable(this.level.getPlayerByUUID(ownerID)).map(HunterPlayer::get).map(HunterPlayer::getSkillHandler);
    }

    /**
     * copy of AbstractFurnaceTileEntity#tick() with modification
     */
    public static void serverTick(Level pLevel, BlockPos pPos, BlockState pState, AlchemicalCauldronBlockEntity pBlockEntity) {
        boolean flagWasLit;
        boolean flagChanged = false;
        if (pBlockEntity.isLit()) {
            pBlockEntity.litTime--;
        }
        if (pBlockEntity.litTime > 0) {
            flagWasLit = true;
            --pBlockEntity.litTime;
        } else {
            flagWasLit = false;
        }

        ItemStack fuel = pBlockEntity.items.get(3);
        ItemStack ingredient = pBlockEntity.items.get(1);
        ItemStack fluid = pBlockEntity.items.get(0);
        boolean hasIngredient = !ingredient.isEmpty();
        boolean hasFuel = !fuel.isEmpty();
        boolean hasFluid = !fluid.isEmpty();
        if (pBlockEntity.isLit() || hasFuel && hasIngredient && hasFluid) {
            RecipeHolder<AlchemicalCauldronRecipe> recipeholder;
            if (hasIngredient && hasFluid) {
                recipeholder = pBlockEntity.quickCheck.getRecipeFor(new AlchemicalCauldronRecipeInput(ingredient, fluid, pBlockEntity.getPlayerSkillHandler()), (ServerLevel) pLevel).orElse(null);
            } else {
                recipeholder = null;
            }

            int i = pBlockEntity.getMaxStackSize();
            if (!pBlockEntity.isLit() && canBurn(pLevel.registryAccess(), recipeholder, pBlockEntity.items, i, pBlockEntity) && pBlockEntity.canPlayerCook(recipeholder)) {
                pBlockEntity.litTime = pBlockEntity.getBurnDuration(fuel);
                pBlockEntity.litDuration = pBlockEntity.litTime;
                if (pBlockEntity.isLit()) {
                    flagChanged = true;
                    pBlockEntity.items.set(3, Helper.shrinkItemStack(fuel, pLevel, pPos)); //Reduce fuel
                }
            }

            if (pBlockEntity.isLit() && canBurn(pLevel.registryAccess(), recipeholder, pBlockEntity.items, i, pBlockEntity) && pBlockEntity.canPlayerCook(recipeholder)) {
                pBlockEntity.cookingProgress++;
                if (pBlockEntity.cookingProgress == pBlockEntity.cookingTotalTime) {
                    pBlockEntity.cookingProgress = 0;
                    pBlockEntity.cookingTotalTime = getTotalCookTime(pLevel, pBlockEntity);
                    if (burn(pLevel.registryAccess(), recipeholder, pBlockEntity.items, i, pBlockEntity)) {
                        pBlockEntity.setRecipeUsed(recipeholder);
                    }

                    flagChanged = true;
                }
            } else {
                pBlockEntity.cookingProgress = 0;
            }
        } else if (pBlockEntity.cookingProgress > 0) {
            pBlockEntity.cookingProgress = Mth.clamp(pBlockEntity.cookingProgress - 2, 0, pBlockEntity.cookingTotalTime);
        }

        if (flagWasLit != pBlockEntity.isLit()) {
            flagChanged = true;
        }

        if (flagChanged) {
            pBlockEntity.setChanged();
        }
    }

    @Override
    protected AbstractContainerMenu createMenu(int id, Inventory player) {
        return new AlchemicalCauldronMenu(id, player, this, this.dataAccess);
    }

    @Override
    protected Component getDefaultName() {
        return Component.translatable("container.vampirism.alchemical_cauldron");
    }

    private boolean canPlayerCook(@Nullable RecipeHolder<AlchemicalCauldronRecipe> recipe) {
        if (recipe == null) return false;
        if (level == null) return false;
        if (recipeChecked == recipe) return true;
        if (ownerID == null) return false;
        Player playerEntity = this.level.getPlayerByUUID(ownerID);
        if (playerEntity == null || !playerEntity.isAlive()) return false;
        HunterPlayer hunter = HunterPlayer.get(playerEntity);
        boolean canCook = recipe.value().canBeCooked(hunter.getLevel(), hunter.getSkillHandler());
        if (canCook) {
            recipeChecked = recipe;
            return true;
        } else {
            recipeChecked = null;
            return false;
        }
    }

    private static boolean canBurn(RegistryAccess pRegistryAccess, @Nullable RecipeHolder<AlchemicalCauldronRecipe> pRecipe, NonNullList<ItemStack> pInventory, int pMaxStackSize, AlchemicalCauldronBlockEntity furnace) {
        if (!pInventory.get(0).isEmpty() && pRecipe != null) {
            ItemStack itemstack = pRecipe.value().assemble(new AlchemicalCauldronRecipeInput(furnace.getIngredient(), furnace.getFluid()));
            if (itemstack.isEmpty()) {
                return false;
            } else {
                ItemStack itemstack1 = pInventory.get(2);
                if (itemstack1.isEmpty()) {
                    return true;
                } else if (!ItemStack.isSameItemSameComponents(itemstack1, itemstack)) {
                    return false;
                } else {
                    // Neo fix: make furnace respect stack sizes in furnace recipes
                    return itemstack1.getCount() + itemstack.getCount() <= pMaxStackSize && itemstack1.getCount() + itemstack.getCount() <= itemstack1.getMaxStackSize() || itemstack1.getCount() + itemstack.getCount() <= itemstack.getMaxStackSize(); // Neo fix: make furnace respect stack sizes in furnace recipes
                }
            }
        } else {
            return false;
        }
    }

    private static boolean burn(RegistryAccess pRegistryAccess, @javax.annotation.Nullable RecipeHolder<AlchemicalCauldronRecipe> pRecipe, NonNullList<ItemStack> pInventory, int pMaxStackSize, AlchemicalCauldronBlockEntity furnace) {
        if (pRecipe != null && canBurn(pRegistryAccess, pRecipe, pInventory, pMaxStackSize, furnace)) {
            ItemStack fluid = pInventory.get(AlchemicalCauldronMenu.FLUID_SLOT);
            ItemStack ingredient = pInventory.get(AlchemicalCauldronMenu.INGREDIENT_SLOT);
            ItemStack newResult = pRecipe.value().assemble(new AlchemicalCauldronRecipeInput(furnace.getIngredient(), furnace.getFluid()));
            ItemStack currentResult = pInventory.get(AlchemicalCauldronMenu.RESULT_SLOT);
            if (currentResult.isEmpty()) {
                pInventory.set(AlchemicalCauldronMenu.RESULT_SLOT, newResult.copy());
            } else if (ItemStack.isSameItemSameComponents(currentResult, newResult)) {
                currentResult.grow(newResult.getCount());
            }
            ItemStackTemplate craftingRemainder = fluid.getCraftingRemainder();
            fluid.shrink(1);
            if (fluid.isEmpty() && craftingRemainder != null) {
                pInventory.set(AlchemicalCauldronMenu.FLUID_SLOT, craftingRemainder.create());
            }
            ingredient.shrink(1);
            return true;
        } else {
            return false;
        }
    }

    private static int getTotalCookTime(Level pLevel, AlchemicalCauldronBlockEntity pBlockEntity) {
        AlchemicalCauldronRecipeInput brewingRecipeInput = new AlchemicalCauldronRecipeInput(pBlockEntity.getIngredient(), pBlockEntity.getFluid());
        return VampirismMod.services().recipes().getRecipeFor(ModRecipes.ALCHEMICAL_CAULDRON_TYPE.get(), brewingRecipeInput, pLevel, pBlockEntity.quickCheck).map(p_300840_ -> p_300840_.value().getCookingTime()).orElse(200);
    }

    private boolean isBurning() {
        return this.dataAccess.get(0) > 0;
    }

    private boolean isCooking() {
        return this.dataAccess.get(2) > 0;
    }

    @Override
    public void setRecipeUsed(@Nullable RecipeHolder<?> pRecipe) {
        if (pRecipe != null) {
            this.recipesUsed.addTo(pRecipe.id(), 1);
        }
    }

    @Nullable
    @Override
    public RecipeHolder<?> getRecipeUsed() {
        return null;
    }

    @Override
    public void fillStackedContents(StackedItemContents contents) {
        for (ItemStack item : this.items) {
            contents.accountStack(item);
        }
    }
}

package de.teamlapen.vampirism.common.world.blockentity;

import de.teamlapen.faction.api.factions.skills.ISkillHandler;
import de.teamlapen.vampirism.VampirismMod;
import de.teamlapen.vampirism.common.core.ModBlockEntities;
import de.teamlapen.vampirism.common.core.ModRecipes;
import de.teamlapen.vampirism.common.util.Helper;
import de.teamlapen.vampirism.common.world.blocks.AlchemyTableBlock;
import de.teamlapen.vampirism.common.world.entity.player.hunter.HunterPlayer;
import de.teamlapen.vampirism.common.world.inventory.AlchemyTableMenu;
import de.teamlapen.vampirism.common.world.items.component.OilContent;
import net.minecraft.core.BlockPos;
import net.minecraft.core.NonNullList;
import net.minecraft.core.UUIDUtil;
import net.minecraft.network.chat.Component;
import net.minecraft.world.ContainerHelper;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.ContainerData;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BaseContainerBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.Arrays;
import java.util.UUID;

public class AlchemyTableBlockEntity extends BaseContainerBlockEntity {

    public static final String KEY_USER = "user";

    private NonNullList<ItemStack> items = NonNullList.withSize(6, ItemStack.EMPTY);
    private @Nullable UUID userID;
    private int brewTime;
    private boolean @Nullable [] lastOilCount;
    private Item ingredient;
    private int fuel;
    private int productColor;
    protected final ContainerData dataAccess = new ContainerData() {
        public int get(int slotId) {
            return switch (slotId) {
                case 0 -> AlchemyTableBlockEntity.this.brewTime;
                case 1 -> AlchemyTableBlockEntity.this.fuel;
                case 2 -> AlchemyTableBlockEntity.this.productColor;
                default -> 0;
            };
        }

        public void set(int slotId, int value) {
            switch (slotId) {
                case 0 -> AlchemyTableBlockEntity.this.brewTime = value;
                case 1 -> AlchemyTableBlockEntity.this.fuel = value;
                case 2 -> AlchemyTableBlockEntity.this.productColor = value;
            }

        }

        public int getCount() {
            return 3;
        }
    };

    public AlchemyTableBlockEntity(@NotNull BlockPos pos, @NotNull BlockState state) {
        super(ModBlockEntities.ALCHEMICAL_TABLE.get(), pos, state);
    }

    @Override
    @NotNull
    protected Component getDefaultName() {
        return Component.translatable("container.vampirism.alchemy_table");
    }

    @Override
    protected @NotNull NonNullList<ItemStack> getItems() {
        return this.items;
    }

    @Override
    protected void setItems(NonNullList<ItemStack> items) {
        this.items = items;
    }

    @NotNull
    @Override
    protected AbstractContainerMenu createMenu(int menuId, @NotNull Inventory playerInventory) {
        return new AlchemyTableMenu(menuId, this.level, playerInventory, this, this.dataAccess);
    }

    @Nullable
    @Override
    public AbstractContainerMenu createMenu(int menuId, @NotNull Inventory playerInventory, @NotNull Player player) {
        if (!canOpen(player)) return null;
        if (Helper.isHunter(player) && !player.getUUID().equals(this.userID)) {
            this.userID = player.getUUID();
            this.setChanged();
        }
        return createMenu(menuId, playerInventory);
    }

    @Nullable
    private ISkillHandler<?> getUserSkillHandler() {
        if (this.level == null || this.userID == null) return null;
        Player user = this.level.getPlayerByUUID(this.userID);
        return user == null ? null : HunterPlayer.get(user).getSkillHandler();
    }

    @Override
    public int getContainerSize() {
        return this.items.size();
    }

    public boolean isEmpty() {
        for (ItemStack itemstack : this.items) {
            if (!itemstack.isEmpty()) {
                return false;
            }
        }

        return true;
    }

    public boolean[] getPotionBits() {
        boolean[] aboolean = new boolean[4];

        for (int i = 0; i < 4; ++i) {
            if (!this.items.get(i).isEmpty()) {
                aboolean[i] = true;
            }
        }

        return aboolean;
    }

    @NotNull
    @Override
    public ItemStack getItem(int p_70301_1_) {
        return p_70301_1_ >= 0 && p_70301_1_ < this.items.size() ? this.items.get(p_70301_1_) : ItemStack.EMPTY;
    }

    @NotNull
    @Override
    public ItemStack removeItem(int p_70298_1_, int p_70298_2_) {
        return ContainerHelper.removeItem(this.items, p_70298_1_, p_70298_2_);

    }

    @NotNull
    @Override
    public ItemStack removeItemNoUpdate(int p_70304_1_) {
        return ContainerHelper.takeItem(this.items, p_70304_1_);

    }

    @Override
    public void setItem(int p_70299_1_, @NotNull ItemStack stack) {
        if (p_70299_1_ >= 0 && p_70299_1_ < this.items.size()) {
            this.items.set(p_70299_1_, stack);
        }
    }

    @Override
    public boolean stillValid(@NotNull Player player) {
        if (this.level.getBlockEntity(this.worldPosition) != this) {
            return false;
        } else {
            return !(player.distanceToSqr((double) this.worldPosition.getX() + 0.5D, (double) this.worldPosition.getY() + 0.5D, (double) this.worldPosition.getZ() + 0.5D) > 64.0D);
        }
    }

    @Override
    public void clearContent() {
        this.items.clear();
    }

    public static void serverTick(@NotNull Level level, @NotNull BlockPos pos, @NotNull BlockState state, @NotNull AlchemyTableBlockEntity blockEntity) {
        ItemStack itemstack = blockEntity.items.get(5);
        if (blockEntity.fuel <= 0 && itemstack.getItem() == Items.BLAZE_POWDER) {
            blockEntity.fuel = 20;
            itemstack.shrink(1);
            blockEntity.setChanged();
        }

        boolean flag = blockEntity.isBrewable(level);
        boolean flag1 = blockEntity.brewTime > 0;
        ItemStack itemstack1 = blockEntity.items.get(4);
        if (flag1) {
            --blockEntity.brewTime;
            boolean flag2 = blockEntity.brewTime == 0;
            if (flag2 && flag) {
                blockEntity.doBrew(level);
                blockEntity.setChanged();
            } else if (!flag) {
                blockEntity.brewTime = 0;
                blockEntity.setChanged();
            } else if (blockEntity.ingredient != itemstack1.getItem()) {
                blockEntity.brewTime = 0;
                blockEntity.setChanged();
            }
        } else if (flag && blockEntity.fuel > 0) {
            --blockEntity.fuel;
            blockEntity.brewTime = 600;
            blockEntity.ingredient = itemstack1.getItem();
            ISkillHandler<?> skills = blockEntity.getUserSkillHandler();
            blockEntity.productColor = VampirismMod.services().recipes().getRecipes().byType(ModRecipes.ALCHEMICAL_TABLE_TYPE.get()).stream().filter(recipe -> recipe.value().isInput(blockEntity.items.get(4)) && (recipe.value().isIngredient(blockEntity.items.getFirst()) || recipe.value().isIngredient(blockEntity.items.get(1))) && recipe.value().canBeBrewed(skills)).map(recipe -> recipe.value().getResultItem()).map(s -> OilContent.getOil(s).value().getColor()).findAny().orElse(0xffffff);
            blockEntity.setChanged();
        }

        boolean[] aboolean = blockEntity.getPotionBits();
        if (!Arrays.equals(aboolean, blockEntity.lastOilCount)) {
            blockEntity.lastOilCount = aboolean;
            if (!(state.getBlock() instanceof AlchemyTableBlock)) {
                return;
            }

            state = state.setValue(AlchemyTableBlock.HAS_BOTTLE_INPUT_0, aboolean[0]);
            state = state.setValue(AlchemyTableBlock.HAS_BOTTLE_INPUT_1, aboolean[1]);
            state = state.setValue(AlchemyTableBlock.HAS_BOTTLE_OUTPUT_0, aboolean[2]);
            state = state.setValue(AlchemyTableBlock.HAS_BOTTLE_OUTPUT_1, aboolean[3]);

            level.setBlock(pos, state, 2);
        }
    }

    private boolean isBrewable(@NotNull Level level) {
        ItemStack itemstack = this.items.get(4);
        if (itemstack.isEmpty()) {
            return false;
        } else if (!isValidInput(level, itemstack)) {
            return false;
        } else {
            for (int i = 0; i < 2; ++i) {
                if (!this.items.get(i + 2).isEmpty()) {
                    continue;
                }
                ItemStack itemstack1 = this.items.get(i);
                if (!itemstack1.isEmpty() && hasRecipe(level, itemstack, itemstack1)) {
                    return true;
                }
            }

            return false;
        }
    }

    private void doBrew(@NotNull Level level) {
        ItemStack itemstack = this.items.get(4);

        for (int i = 0; i < 2; i++) {
            if (this.items.get(i + 2).isEmpty()) {
                ItemStack stack = getOutput(level, itemstack, this.items.get(i));
                if (stack.isEmpty()) {
                    continue;
                }
                this.items.get(i).shrink(1);
                this.items.set(i + 2, stack);
            }
        }
        BlockPos blockpos = this.getBlockPos();

        itemstack = Helper.shrinkItemStack(itemstack, level, blockpos); //Reduce ingredient by 1

        this.items.set(4, itemstack);
        level.levelEvent(1035, blockpos, 0);
    }

    public boolean canPlaceItem(int slot, @NotNull ItemStack stack) {
        return switch (slot) {
            case AlchemyTableMenu.OIL_SLOT_1, AlchemyTableMenu.OIL_SLOT_2 -> isValidIngredient(this.level, stack) && this.getItem(slot).isEmpty();
            case AlchemyTableMenu.INGREDIENT_SLOT -> isValidInput(this.level, stack);
            case AlchemyTableMenu.FUEL_SLOT -> stack.getItem() == Items.BLAZE_POWDER;
            default -> false;
        };
    }

    private boolean hasRecipe(@NotNull Level level, ItemStack input, @NotNull ItemStack ingredient) {
        ISkillHandler<?> skills = getUserSkillHandler();
        return VampirismMod.services().recipes().getRecipes().byType(ModRecipes.ALCHEMICAL_TABLE_TYPE.get()).stream().anyMatch(recipe -> recipe.value().isInput(input) && recipe.value().isIngredient(ingredient) && recipe.value().canBeBrewed(skills));
    }

    public boolean isValidIngredient(@NotNull Level level, @NotNull ItemStack stack) {
        return VampirismMod.services().recipes().getRecipes().byType(ModRecipes.ALCHEMICAL_TABLE_TYPE.get()).stream().anyMatch(recipe -> recipe.value().isIngredient(stack));
    }

    public boolean isValidInput(@NotNull Level level, @NotNull ItemStack stack) {
        return VampirismMod.services().recipes().getRecipes().byType(ModRecipes.ALCHEMICAL_TABLE_TYPE.get()).stream().anyMatch(recipe -> recipe.value().isInput(stack));
    }

    public @NotNull ItemStack getOutput(@NotNull Level level, @NotNull ItemStack input, @NotNull ItemStack ingredient) {
        ISkillHandler<?> skills = getUserSkillHandler();
        return VampirismMod.services().recipes().getRecipes().byType(ModRecipes.ALCHEMICAL_TABLE_TYPE.get()).stream().filter(recipe -> recipe.value().canBeBrewed(skills)).map(recipe -> recipe.value().getResult(input, ingredient)).filter(a -> !a.isEmpty()).findFirst().orElse(ItemStack.EMPTY);
    }

    @Override
    public void loadAdditional(@NotNull ValueInput input) {
        super.loadAdditional(input);
        this.items = NonNullList.withSize(this.getContainerSize(), ItemStack.EMPTY);
        ContainerHelper.loadAllItems(input.childOrEmpty("items"), this.items);
        this.brewTime = input.getShortOr("BrewTime", (short) 0);
        this.fuel = input.getByteOr("Fuel", (byte) 0);
        this.userID = input.read(KEY_USER, UUIDUtil.CODEC).orElse(null);
    }

    @Override
    public void saveAdditional(@NotNull ValueOutput output) {
        super.saveAdditional(output);
        output.putShort("BrewTime", (short) this.brewTime);
        ContainerHelper.saveAllItems(output.child("items"), this.items);
        output.putByte("Fuel", (byte) this.fuel);
        if (this.userID != null) {
            output.store(KEY_USER, UUIDUtil.CODEC, this.userID);
        }
    }
}

package de.teamlapen.vampirism.common.world.blockentity;

